syntax = "proto3";

package depot.v1;

// Inventory, replenishment and supplier operations for the distribution
// centres ("depots").
//
// DepotService is not published through the public API gateway. Its callers
// are other platform services: storefront-api, replenishment-worker,
// finance-etl and the warehouse terminal BFF. Everything below expects a
// platform access token in the `authorization` metadata header.
service DepotService {
  // Finance cost reporting. Backs the /reports page in the ops console.
  rpc BuildCostReport(BuildCostReportRequest) returns (CostReport);

  // Throughput tiles on the depot dashboard.
  rpc GetDepotThroughput(GetDepotThroughputRequest) returns (DepotThroughput);

  // INTERNAL ONLY. Writes a manual correction to a stock position.
  // Not in the gateway's route table; replenishment-worker calls it directly
  // over the pod network.
  rpc AdjustStock(AdjustStockRequest) returns (StockAdjustment);

  // INTERNAL ONLY. Moves stock between two depots.
  rpc TransferStock(TransferStockRequest) returns (StockTransfer);

  rpc GetPurchaseOrder(GetPurchaseOrderRequest) returns (PurchaseOrder);
  rpc GetGoodsReceipt(GetGoodsReceiptRequest) returns (GoodsReceipt);

  rpc SubmitCycleCount(SubmitCycleCountRequest) returns (CycleCount);
  rpc ApproveCycleCount(ApproveCycleCountRequest) returns (CycleCount);

  // Server stream drained by finance-etl every fifteen minutes.
  rpc StreamInventoryAudit(StreamInventoryAuditRequest) returns (stream InventoryAuditEvent);

  rpc GetInvoiceDocument(GetInvoiceDocumentRequest) returns (InvoiceDocument);
  rpc GetSupplierStatement(GetSupplierStatementRequest) returns (SupplierStatement);
}

enum ThroughputGrouping {
  THROUGHPUT_GROUPING_UNSPECIFIED = 0;
  THROUGHPUT_GROUPING_DAY = 1;
  THROUGHPUT_GROUPING_SHIFT = 2;
  THROUGHPUT_GROUPING_LANE = 3;
}

message BuildCostReportRequest {
  string depot_id = 1;
  // Inclusive ISO dates, e.g. "2026-04-01".
  string from_date = 2;
  string to_date = 3;
  // Column the report is grouped and ordered by, chosen in the ops console.
  string group_by = 4;
  // "asc" or "desc".
  string sort_direction = 5;
  // Extra predicate the console's advanced filter builds, e.g.
  // "line_total > 500 and supplier_id = 'S-1188'". Empty when unused.
  string filter_expression = 6;
  int32 row_limit = 7;
}

message CostReportRow {
  string bucket = 1;
  double total_cost = 2;
  int64 line_count = 3;
}

message CostReport {
  string depot_id = 1;
  repeated CostReportRow rows = 2;
  double grand_total = 3;
}

message GetDepotThroughputRequest {
  string depot_id = 1;
  int32 window_days = 2;
  ThroughputGrouping grouping = 3;
  bool sort_descending = 4;
}

message ThroughputBucket {
  string bucket = 1;
  int32 picks = 2;
  int32 short_picks = 3;
}

message DepotThroughput {
  string depot_id = 1;
  repeated ThroughputBucket buckets = 2;
}

message AdjustStockRequest {
  string depot_id = 1;
  string sku = 2;
  // Signed correction applied to on_hand. Never zero.
  int32 quantity_delta = 3;
  // One of the reason codes in stock_adjustment_reasons.
  string reason_code = 4;
  string note = 5;
}

message StockAdjustment {
  string id = 1;
  string depot_id = 2;
  string sku = 3;
  int32 quantity_delta = 4;
  int32 on_hand_after = 5;
  string reason_code = 6;
  string recorded_by = 7;
  string recorded_at = 8;
}

message TransferStockRequest {
  string from_depot_id = 1;
  string to_depot_id = 2;
  string sku = 3;
  int32 quantity = 4;
  string reason_code = 5;
}

message StockTransfer {
  string id = 1;
  string from_depot_id = 2;
  string to_depot_id = 3;
  string sku = 4;
  int32 quantity = 5;
  string recorded_by = 6;
  string recorded_at = 7;
}

message GetPurchaseOrderRequest {
  string purchase_order_id = 1;
  bool include_lines = 2;
}

message PurchaseOrderLine {
  int32 line_no = 1;
  string sku = 2;
  int32 quantity_ordered = 3;
  double unit_cost = 4;
}

message PurchaseOrder {
  string id = 1;
  string depot_id = 2;
  string supplier_id = 3;
  string supplier_contract_ref = 4;
  string status = 5;
  double total_cost = 6;
  string expected_at = 7;
  repeated PurchaseOrderLine lines = 8;
}

message GetGoodsReceiptRequest {
  string goods_receipt_id = 1;
}

message GoodsReceiptLine {
  int32 line_no = 1;
  string sku = 2;
  int32 quantity_received = 3;
  int32 quantity_rejected = 4;
}

message GoodsReceipt {
  string id = 1;
  string depot_id = 2;
  string purchase_order_id = 3;
  string received_at = 4;
  string received_by = 5;
  repeated GoodsReceiptLine lines = 6;
}

message SubmitCycleCountRequest {
  string depot_id = 1;
  string sku = 2;
  int32 counted_quantity = 3;
  // Stamped by the warehouse terminal BFF with the picker's staff id.
  // Interactive callers leave it out.
  string actor_user_id = 4;
  string counted_at = 5;
}

message ApproveCycleCountRequest {
  string cycle_count_id = 1;
  string depot_id = 2;
  // Set only by the terminal BFF when a supervisor approves on a shared
  // terminal. Interactive callers leave it out.
  string actor_user_id = 3;
  string note = 4;
}

message CycleCount {
  string id = 1;
  string depot_id = 2;
  string sku = 3;
  int32 counted_quantity = 4;
  int32 expected_quantity = 5;
  string status = 6;
  string counted_by = 7;
  string approved_by = 8;
  string counted_at = 9;
}

message StreamInventoryAuditRequest {
  string depot_id = 1;
  // Inclusive ISO timestamp; the ETL job keeps its own high-water mark.
  string since = 2;
  // Cost lines are finance-only and roughly triple the payload.
  bool include_cost_lines = 3;
}

message InventoryAuditEvent {
  string id = 1;
  string depot_id = 2;
  string sku = 3;
  string event_type = 4;
  int32 quantity_delta = 5;
  string recorded_by = 6;
  string recorded_at = 7;
  // Only populated for finance callers.
  double unit_cost = 8;
  string supplier_contract_ref = 9;
}

message GetInvoiceDocumentRequest {
  string supplier_invoice_id = 1;
  // Object name of the scan on the shared documents volume, as the
  // procurement UI already knows it, e.g. "2026/04/INV-33812.pdf".
  string document_name = 2;
}

message InvoiceDocument {
  string file_name = 1;
  string content_type = 2;
  int64 size_bytes = 3;
  bytes contents = 4;
}

message GetSupplierStatementRequest {
  string supplier_id = 1;
  // Object name of the monthly statement, e.g. "S-1188/2026-04.csv".
  string statement_name = 2;
}

message SupplierStatement {
  string file_name = 1;
  string content_type = 2;
  int64 size_bytes = 3;
  bytes contents = 4;
}

